metrics.workdir_dsl:
workspace "Bank Portal" "C4 model of the online banking platform" {

    !identifiers hierarchical

    model {

        customer = person "Bank Customer" "Uses the platform to manage their accounts, move money, and track their activity"

        bankPortal = softwareSystem "Bank Portal" "Online banking platform owned and operated by our company" {

            webPortal = container "Web Portal" "Web portal where customers log in and manage their accounts" "Web application"
            mobileAppBackend = container "Mobile App Backend" "Backend that serves the bank's mobile app" "REST API"
            accountService = container "Account Service" "Holds the customer account records" "Service"
            transactionService = container "Transaction Service" "Processes deposits, withdrawals, and transfers" "Service"
            paymentService = container "Payment Service" "Executes card payments and bank transfers" "Service"
            cardService = container "Card Service" "Manages debit and credit cards" "Service"
            fraudDetectionService = container "Fraud Detection Service" "Scores transactions for fraud" "Service"
            notificationService = container "Notification Service" "Sends email and SMS alerts" "Service"
            onboardingService = container "Onboarding Service" "Verifies new customers" "Service"
            statementsService = container "Statements Service" "Generates monthly statements" "Service"
            directDebitService = container "Direct Debit Service" "Processes standing orders and direct debits" "Service"
            exchangeRatesService = container "Exchange Rates Service" "Provides currency conversion rates" "Service"
            batchScheduler = container "Batch Scheduler" "Runs the nightly interest calculation and reconciliation" "Batch job"

            eventQueue = container "Event Queue" "Carries internal events between the application parts" "Message queue" "Queue"
            ledgerDb = container "Ledger Database" "Stores every account movement" "Database" "Database"
            customerDb = container "Customer Database" "Stores account and profile records" "Database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail" "Database" "Database"
            cache = container "Cache" "Stores sessions and frequently read account data" "Cache" "Cache"
            documentStore = container "Document Store" "Holds the generated statement PDFs" "Document store" "DocumentStore"
        }

        cardPaymentNetwork = softwareSystem "Card Payment Network" "Card payment network operated by a different organization" "External"
        creditReferenceAgency = softwareSystem "Credit Reference Agency" "Credit reference agency operated by a different organization" "External"

        customer -> bankPortal.webPortal "logs in to manage accounts, move money, and track activity" "HTTPS"
        customer -> bankPortal.mobileAppBackend "manages accounts, moves money, and tracks activity via the bank's mobile app" "HTTPS"

        bankPortal.webPortal -> bankPortal.accountService "manages accounts through" "HTTPS"
        bankPortal.webPortal -> bankPortal.transactionService "submits deposits, withdrawals, and transfers to" "HTTPS"
        bankPortal.webPortal -> bankPortal.paymentService "initiates card payments and bank transfers through" "HTTPS"
        bankPortal.webPortal -> bankPortal.cardService "manages debit and credit cards through" "HTTPS"
        bankPortal.webPortal -> bankPortal.statementsService "requests monthly statements from" "HTTPS"
        bankPortal.webPortal -> bankPortal.directDebitService "manages standing orders and direct debits through" "HTTPS"

        bankPortal.mobileAppBackend -> bankPortal.accountService "manages accounts through" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.transactionService "submits deposits, withdrawals, and transfers to" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.paymentService "initiates card payments and bank transfers through" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.cardService "manages debit and credit cards through" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.statementsService "requests monthly statements from" "HTTPS"
        bankPortal.mobileAppBackend -> bankPortal.directDebitService "manages standing orders and direct debits through" "HTTPS"

        bankPortal.paymentService -> cardPaymentNetwork "routes card authorisations through" "HTTPS"
        bankPortal.onboardingService -> creditReferenceAgency "performs credit checks through" "HTTPS"

        bankPortal.transactionService -> bankPortal.ledgerDb "updates" "SQL"
        bankPortal.transactionService -> bankPortal.fraudDetectionService "scores transactions with" "HTTPS"
        bankPortal.transactionService -> bankPortal.eventQueue "publishes events to" "events"

        bankPortal.notificationService -> bankPortal.eventQueue "consumes events from" "events"

        bankPortal.statementsService -> bankPortal.ledgerDb "reads" "SQL"
        bankPortal.statementsService -> bankPortal.documentStore "writes" "files"

        bankPortal.batchScheduler -> bankPortal.ledgerDb "reads and writes" "SQL"
        bankPortal.batchScheduler -> bankPortal.customerDb "reads and writes" "SQL"

        bankPortal.paymentService -> bankPortal.cardService "requests card information from" "HTTPS"
        bankPortal.paymentService -> bankPortal.exchangeRatesService "requests currency conversion rates from" "HTTPS"

        bankPortal.onboardingService -> bankPortal.customerDb "reads" "SQL"
    }

    views {
        systemContext bankPortal "SystemContext" {
            include *
            autoLayout
            title "System Context for Bank Portal"
        }

        container bankPortal "Containers" {
            include *
            autoLayout
            title "Containers for Bank Portal"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Queue" {
                shape Pipe
            }
            element "Cache" {
                shape Cylinder
            }
            element "DocumentStore" {
                shape Cylinder
            }
        }
    }

    configuration {
        scope softwareSystem
    }
}
